        {"topic": "migration_options_azure_migrate_data_box", "question": "Which statement about Azure Migrate is correct?", "choices": ["It can provide cost and readiness assessments for on-premises servers before migration begins", "It requires purchasing a physical appliance to function", "It only supports migrating file shares", "It cannot assess databases"], "answerIndex": 0, "explanation": "Azure Migrate's assessment tools estimate readiness and right-sized Azure costs before a workload is actually migrated."},
        {"topic": "migration_options_azure_migrate_data_box", "question": "A business wants to evaluate how much a set of on-premises VMs would cost to run in Azure before committing to migrate. Which tool helps with this?", "choices": ["Azure Migrate", "Azure Data Box", "AzCopy", "Azure File Sync"], "answerIndex": 0, "explanation": "Azure Migrate's assessment feature estimates Azure costs and readiness for on-premises VMs before migration."},
        {"topic": "migration_options_azure_migrate_data_box", "question": "What kind of appliance is Azure Data Box Heavy designed for?", "choices": ["Transferring extremely large data volumes (petabyte scale) offline via a ruggedized physical device shipped to Microsoft", "A virtual appliance that runs entirely in the cloud", "A tool for real-time database replication", "A network security appliance"], "answerIndex": 0, "explanation": "Data Box Heavy is a ruggedized physical device built to move petabyte-scale data sets offline."},
