        {"topic": "encryption_and_key_management", "question": "What is the difference between encryption at rest and encryption in transit?", "choices": ["They are two names for the same thing", "Encryption at rest protects stored data, while encryption in transit protects data moving between systems", "Encryption at rest only applies to virtual machines", "Encryption in transit only applies to backups"], "answerIndex": 1, "explanation": "Encryption at rest protects data while stored (e.g., in disks or databases), while encryption in transit protects data as it moves between services, apps, and users."},
        {"topic": "encryption_and_key_management", "question": "What is Azure Key Vault primarily used for?", "choices": ["Hosting virtual machines", "Securely storing and controlling access to secrets, encryption keys, and certificates", "Running containerized applications", "Monitoring network traffic"], "answerIndex": 1, "explanation": "Azure Key Vault centralizes secure storage and access control for secrets, encryption keys, and certificates."},
        {"topic": "encryption_and_key_management", "question": "Why is storing secrets directly in application code or configuration files discouraged compared to using Azure Key Vault?", "choices": ["It's actually the recommended best practice", "It increases the risk of exposing hard-coded credentials and weakens secret governance", "Application code cannot store secrets at all", "Configuration files are always encrypted automatically"], "answerIndex": 1, "explanation": "Hard-coding secrets in code or config increases exposure risk; centralizing them in Key Vault improves governance and reduces that risk."},
