# Every distinct topic slug per domain, derived from SNIPPETS (16 + 29 + 17
# = 62 total). This is the denominator for "concept coverage" — see
# service.py's get_progress_summary, which won't let a domain's mastery
# reach 100% until every one of its topics has actually been quizzed at
# least once (not just answered correctly a lot on a narrow slice).
TOPICS_BY_DOMAIN = {
    domain: sorted({entry["topic"] for entry in SNIPPETS[domain]}) for domain in DOMAINS
}


